mapper.sql:
INNER JOIN item iParent ON i.parent_id = iParent.id
WHERE i.site_id = #{siteId}




AND iParent.path IN (#{path}, CONCAT(#{path}, '/index.xml'))
AND (
	i.system_type <> '${systemTypeFolder}'
	OR
	NOT EXISTS (
		SELECT *
		FROM item page
		WHERE page.site_id = i.site_id
		AND page.system_type = '${systemTypePage}'
		AND page.path = CONCAT(i.path, '/index.xml')
	)
)

	AND i.locale_code = #{localeCode}



	AND i.label LIKE #{pattern}


	AND i.path NOT IN

		#{exclude}, CONCAT(#{exclude}, '/index.xml')



	AND i.system_type IN

		#{type}



	AND i.system_type NOT IN

		#{type}


GROUP BY i.id

mapper.select:





		ORDER BY i.label ${order}, i.path ${order}


		ORDER BY IF(FIELD(i.system_type, '${systemTypeFolder}')=0,1,0), FIELD(i.system_type, '${systemTypeFolder}'),
		i.label ${order}, i.path ${order}


		ORDER BY i.last_modified_on ${order}, i.label ${order}, i.path ${order}


		ORDER BY i.label ${order}, i.path ${order}


LIMIT #{offset}, #{limit}


WHERE s.id = #{siteId}
AND i.path = #{path}

GROUP BY i.id
LIMIT 0, 1

(

	WHERE s.id = #{siteId}
	AND i.ignored = 0

	AND i.path = CONCAT(TRIM(TRAILING '/' FROM #{path}), '/index.xml')

	GROUP BY i.id
)
UNION
(

	WHERE s.id = #{siteId}
	AND i.path = #{path}
	AND i.ignored = 0

	GROUP BY i.id
	)
LIMIT 0, 1

mapper.delete:
DELETE FROM item
WHERE site_id = #{siteId}
AND (
	path = #{path}

	OR (   
		path = TRIM(TRAILING '/index.xml' FROM #{path})
		AND EXISTS (SELECT 1
		FROM item
		WHERE site_id = #{siteId}
		AND path = #{path}
		AND system_type = '${systemTypePage}')
	)

)

mapper.update:
UPDATE item set state = (state | #{onStatesBitMap}) & ~#{offStatesBitMap}
WHERE site_id = #{siteId} AND path IN

	#{path}

AND system_type <> '${systemTypeFolder}'

UPDATE item i INNER JOIN site s ON i.site_id = s.id
SET path = #{newPath},
i.state = CASE WHEN i.system_type = '${systemTypeFolder}' THEN 0 ELSE (i.state | #{onStatesBitMap}) & ~#{offStatesBitMap} END,
i.preview_url = IF(i.system_type = '${systemTypeFolder}', NULL, #{newPreviewUrl}),
i.last_modified_by = #{userId},
i.last_modified_on = NOW()

	, i.label = #{label}


	, i.parent_id = #{parentId}

WHERE s.site_id = #{siteId} AND s.deleted = 0 AND i.path = #{previousPath}

UPDATE item i INNER JOIN site s
ON i.site_id = s.id
	SET i.locked_by = #{lockOwnerId}, i.state = i.state | #{lockedBitOn}
WHERE s.site_id = #{siteId}
  AND s.deleted = 0
  AND i.path = #{path}
  AND i.system_type <> '${systemTypeFolder}'

UPDATE item i INNER JOIN site s
ON i.site_id = s.id
	SET i.locked_by = null, i.state = i.state & #{lockedBitOff}
WHERE s.site_id = #{siteId}
  AND s.deleted = 0
  AND i.path = #{path}

mapper.select:
SELECT i.path, i.state
FROM item i INNER JOIN site s ON i.site_id = s.id
WHERE s.site_id = #{siteId}
AND i.path IN

	#{path}

mapper.update:
UPDATE item, (SELECT id, max(potential_parent_path) as calculated_parent_path, (SELECT p.id FROM item p WHERE (p.path = max(potential_parent_path)) and p.site_id = #{siteId}) AS calculated_parent_id FROM (SELECT candidates.id, candidates.path, candidates.parent_id, (SELECT p.id FROM item p WHERE (p.path = candidates.parent_path) AND p.site_id = #{siteId}) AS potential_parent_id, candidates.parent_path as potential_parent_path FROM ( SELECT id, parent_id, path, reverse(substr(reverse(trim('/index.xml' from path)), locate('/', reverse(trim('/index.xml' from path)))+1)) AS parent_path FROM item WHERE site_id = #{siteId} AND item.path IN
UNION SELECT id, parent_id, path, concat(reverse(substr(reverse(trim('/index.xml' from path)), locate('/', reverse(trim('/index.xml' from path)))+1)), '/index.xml') AS parent_path FROM item WHERE site_id = #{siteId} AND item.path IN
) AS candidates ) AS mapped WHERE potential_parent_id IS NOT NULL GROUP BY id ) AS updates SET item.parent_id = updates.calculated_parent_id WHERE item.id = updates.id

mapper.select:
SELECT COUNT(1)
FROM item i
INNER JOIN site s ON s.id = i.site_id
WHERE (i.state & #{itemStateMask}) = #{itemStateMask}
AND s.site_id = #{siteId}
AND s.deleted = 0
AND i.path IN

	#{path}

mapper.sql:
WITH RECURSIVE children AS ( SELECT i.id, i.path, i.label, i.system_type, i.mime_type FROM item i INNER JOIN site s ON s.id = i.site_id WHERE i.path IN
#{path}
AND s.site_id = #{siteId} UNION SELECT i.id, i.path, i.label, i.system_type, i.mime_type FROM item i, children WHERE i.parent_id = children.id ) SELECT path, label AS meta_label, mime_type AS meta_mime_type, system_type AS meta_system_type FROM children WHERE system_type <> '${systemTypeFolder}' AND path NOT IN
#{path}

mapper.update:
UPDATE item,
(
	SELECT child.id AS childId,
	(
		SELECT i.id
		FROM item i
		WHERE i.site_id = #{siteId}
		AND i.path = #{path}
	) AS newParentId
	FROM item child
	INNER JOIN item parent ON child.parent_id = parent.id
	WHERE child.site_id = #{siteId}
	AND parent.path = CONCAT(#{path}, '/index.xml')
) AS updates
SET item.parent_id = updates.newParentId
WHERE item.id = updates.childId;
